 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(x for row in grid for x in row), key=lambda x: sum(r.count(x) for r in grid))
    # Locate the repeated endpoint color: a straight run on an edge marks a boundary.
    edge_runs = {}
    for color in set(x for row in grid for x in row if x != background):
        runs = []
        for r in range(h):
            if grid[r][0] == color:
                runs.append(('left', r))
            if grid[r][w-1] == color:
                runs.append(('right', r))
        for c in range(w):
            if grid[0][c] == color:
                runs.append(('top', c))
            if grid[h-1][c] == color:
                runs.append(('bottom', c))
        edge_runs[color] = runs
    # For each isolated 1, fill its row/column toward the nearest boundary marker,
    # changing the 1 nearest the marker to 4. Marker color differs by task.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                continue
            candidates = []
            for color, runs in edge_runs.items():
                for side, pos in runs:
                    if side == 'left' and pos == r and c > 0:
                        candidates.append((c, color, side))
                    elif side == 'right' and pos == r and c < w-1:
                        candidates.append((w-1-c, color, side))
                    elif side == 'top' and pos == c and r > 0:
                        candidates.append((r, color, side))
                    elif side == 'bottom' and pos == c and r < h-1:
                        candidates.append((h-1-r, color, side))
            if not candidates:
                continue
            _, color, side = min(candidates)
            if side == 'left':
                for x in range(c+1, w):
                    out[r][x] = 1
                out[r][c] = 4
            elif side == 'right':
                for x in range(0, c):
                    out[r][x] = 1
                out[r][c] = 4
            elif side == 'top':
                for y in range(r+1, h):
                    out[y][c] = 1
                out[r][c] = 4
            else:
                for y in range(0, r):
                    out[y][c] = 1
                out[r][c] = 4
    return out
