 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Each color-3 seed extends in a straight line toward the nearest matching
    # border bar (color 1). The seed changes to 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                continue
            out[r][c] = 4
            candidates = []
            if c == 0 and grid[r][w - 1] == 1:
                candidates.append((w - 1 - c, 0, 1))
            if c == w - 1 and grid[r][0] == 1:
                candidates.append((c, 0, -1))
            if r == 0 and grid[h - 1][c] == 1:
                candidates.append((h - 1 - r, 1, 0))
            if r == h - 1 and grid[0][c] == 1:
                candidates.append((r, -1, 0))
            # When a rail is not on the same edge coordinate, match by the
            # nearest rail pixel on any boundary, in the direction of that rail.
            for rr in range(h):
                for cc in range(w):
                    if grid[rr][cc] != 1:
                        continue
                    if rr in (0, h-1) and cc == c:
                        candidates.append((abs(rr-r), 1 if rr > r else -1, 0))
                    if cc in (0, w-1) and rr == r:
                        candidates.append((abs(cc-c), 0, 1 if cc > c else -1))
            if not candidates:
                continue
            _, dr, dc = min(candidates, key=lambda a: a[0])
            y, x = r + dr, c + dc
            while 0 <= y < h and 0 <= x < w and grid[y][x] not in (1, 3):
                out[y][x] = 3
                y += dr
                x += dc
    return out
