            options = []
            if grid[r][0] == rail and c > 0:
                options.append((c, 0, -1))
            if grid[r][w - 1] == rail and c < w - 1:
                options.append((w - 1 - c, 0, 1))
            if grid[0][c] == rail and r > 0:
                options.append((r, -1, 0))
            if grid[h - 1][c] == rail and r < h - 1:
                options.append((h - 1 - r, 1, 0))
            if not options:
                continue
            _, dr, dc = min(options, key=lambda x: x[0])
            out[r][c] = 4
            y, x = r + dr, c + dc
            while 0 <= y < h and 0 <= x < w and grid[y][x] == background:
                out[y][x] = color
                y += dr
                x += dc
