 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The edge runs of 1s are rails. Every 3 marker projects a 3-colored
    # ray toward the nearest rail; the marker itself changes to 4.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    rail = max((v for v in counts if v != background), key=lambda v: counts[v])
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (background, rail):
                continue
            candidates = []
            if grid[r][0] == rail:
                candidates.append((c, 'left'))
            if grid[r][w-1] == rail:
                candidates.append((w-1-c, 'right'))
            if grid[0][c] == rail:
                candidates.append((r, 'up'))
            if grid[h-1][c] == rail:
                candidates.append((h-1-r, 'down'))
            if not candidates:
                continue
            direction = min(candidates, key=lambda item: item[0])[1]
            out[r][c] = 4
            if direction == 'left':
                cells = ((r,x) for x in range(c-1, -1, -1))
            elif direction == 'right':
                cells = ((r,x) for x in range(c+1, w))
            elif direction == 'up':
                cells = ((y,c) for y in range(r-1, -1, -1))
            else:
                cells = ((y,c) for y in range(r+1, h))
            for y,x in cells:
                if grid[y][x] == rail:
                    break
                if grid[y][x] == background:
                    out[y][x] = color
    return out
  ",
 "cross_profile": false
}

