 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The marker triangle points toward the bottom-left rail. Continue each
    # diagonal trail down-left; the original marked pixels turn to 4.
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in markers:
        out[r][c] = 4
    # Repeated diagonal bands continue through the lower-left quadrant.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 9:
                continue
            # A filled pixel lies on a down-left diagonal from an existing marker.
            if any(r > mr and c < mc and (mr + mc) == (r + c) for mr, mc in markers):
                out[r][c] = 3
    return out
