 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in markers:
        out[r][c] = 4
    # Continue the marker's down-left staircase: a marker emits along its
    # down-left diagonal until it meets the bottom rail, while preserving the
    # same staircase's horizontal runs between diagonals.
    for r, c in markers:
        # Cells sharing the diagonal down-left from this seed
        rr, cc = r + 1, c - 1
        while rr < h - 1 and cc >= 0:
            if grid[rr][cc] == 9:
                out[rr][cc] = 3
            rr += 1
            cc -= 1
    # Complete the horizontally aligned rows of the staircase, stopping at the edge rail.
    for r in range(h - 1):
        cs = [c for rr, c in markers if rr == r]
        if cs:
            for c in range(min(cs), max(cs) + 1):
                if grid[r][c] == 9:
                    out[r][c] = 3
    return out
