    # A marker changes to 4 and the ray is filled with its original color.
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in pts:
        # Outer-edge seeds emit inward toward the other 1-colored rail.
        options = []
        if grid[r][0] == 3:
            options.append((c, 0, 1))
        if grid[r][w-1] == 3:
            options.append((w-1-c, 0, -1))
        if grid[0][c] == 3:
            options.append((r, 1, 0))
        if grid[h-1][c] == 3:
            options.append((h-1-r, -1, 0))
        if options:
            _, dr, dc = min(options)
            out[r][c] = 4
            y, x = r+dr, c+dc
            while 0 <= y < h and 0 <= x < w and grid[y][x] == 9:
                out[y][x] = 3
                y += dr
                x += dc
    # In the common arrangement, marks are interior and bracketed by bars;
    # preserve them while extending each diagonal staircase through its hull.
    for r, c in pts:
        out[r][c] = 4
    # Complete rows/columns leading from markers to aligned 1 rails.
    for r, c in pts:
        if any(grid[r][x] == 1 for x in range(w)):
            end = min((x for x in range(w) if grid[r][x] == 1), key=lambda x: abs(x-c))
            step = 1 if end > c else -1
            for x in range(c+step, end, step):
                if grid[r][x] == 9: out[r][x] = 3
        if any(grid[y][c] == 1 for y in range(h)):
            end = min((y for y in range(h) if grid[y][c] == 1), key=lambda y: abs(y-r))
            step = 1 if end > r else -1
            for y in range(r+step, end, step):
                if grid[y][c] == 9: out[y][c] = 3
    # Fill contiguous 3-pattern region in the corner bounded by two bars.
